import { describe, expect, it } from 'vitest';
import { floorDiv } from '../../src/logic/arith';
import { formatScore } from '../../src/logic/format';
import { isPass, scoreTenths } from '../../src/logic/score';
import { parseDecimal } from '../../src/validation/parse';
import { toViewModel, type RawInputs, type ViewModel } from '../../src/ui/view-model';
import { MESSAGES } from '../../src/messages';

// S-1 Score and pass/fail verdict (test-plan.md T-S1.1..T-S1.8).
// Every comparison is on integers or strings: E = earned × 100, T = total × 100, P = pass × 10 (ADR-002).
// Score strings ("76.0%") are the AC values; verdict words come from messages.ts (M-4, M-5).

const PASS = MESSAGES['M-4'];
const FAIL = MESSAGES['M-5'];

function vm(earned: string, total: string, pass: string): ViewModel {
  const raw: RawInputs = { earned, total, pass };
  return toViewModel(raw);
}

/** What the result area shows: "<score>%" and the verdict word, or null when no score is shown. */
function shown(model: ViewModel): { score: string; verdict: string } | null {
  if (model.state !== 'result') return null;
  return { score: `${model.score}%`, verdict: model.verdictText };
}

describe('T-S1.1 17.5 of 23 at the pre-filled 70 → "76.0%", Pass', () => {
  it('scales to E = 1750, T = 2300, P = 700', () => {
    expect(parseDecimal('17.5', 2)).toEqual({ ok: true, value: 1750 });
    expect(parseDecimal('23', 2)).toEqual({ ok: true, value: 2300 });
    expect(parseDecimal('70', 1)).toEqual({ ok: true, value: 700 });
  });

  it('floors 1,750,000 / 2300 = 760.8… to 760 tenths and passes (1,750,000 ≥ 1,610,000)', () => {
    expect(scoreTenths(1750, 2300)).toBe(760);
    expect(formatScore(760)).toBe('76.0');
    expect(isPass(1750, 2300, 700)).toBe(true);
  });

  it('view model shows "76.0%" and "Pass" and announces both', () => {
    const model = vm('17.5', '23', '70');
    expect(shown(model)).toEqual({ score: '76.0%', verdict: PASS });
    expect(model.state === 'result' && model.verdict).toBe('pass');
    expect(model.announcement.startsWith(`76.0%, ${PASS}`)).toBe(true);
  });
});

describe('T-S1.2 17.5 of 25 (exactly 70%) → "70.0%", Pass', () => {
  it('E × 1000 equals P × T exactly (1,750,000 = 1,750,000), so it is a pass', () => {
    expect(1750 * 1000).toBe(700 * 2500);
    expect(isPass(1750, 2500, 700)).toBe(true);
    expect(scoreTenths(1750, 2500)).toBe(700);
    expect(shown(vm('17.5', '25', '70'))).toEqual({ score: '70.0%', verdict: PASS });
  });
});

describe('T-S1.3 17.49 of 25 (69.96%) → "69.9%", Fail, never "70.0%"', () => {
  it('1,749,000 < 1,750,000 is a fail, and 699.6 tenths floors to 699', () => {
    expect(isPass(1749, 2500, 700)).toBe(false);
    expect(scoreTenths(1749, 2500)).toBe(699);
    expect(shown(vm('17.49', '25', '70'))).toEqual({ score: '69.9%', verdict: FAIL });
  });

  it('no prefix typed on the way to "17.49" shows "70.0%"', () => {
    const steps = ['1', '17', '17.', '17.4', '17.49'];
    const scores = steps.map((earned) => shown(vm(earned, '25', '70'))?.score);
    expect(scores).toEqual(['4.0%', '68.0%', '68.0%', '69.6%', '69.9%']);
    expect(scores).not.toContain('70.0%');
  });
});

describe('T-S1.4 2 of 3 → "66.6%" (rounded down, not "66.7%"), Fail', () => {
  it('floorDiv(200,000, 300) = 666', () => {
    expect(floorDiv(200_000, 300)).toBe(666);
    expect(scoreTenths(200, 300)).toBe(666);
    expect(formatScore(666)).toBe('66.6');
    expect(shown(vm('2', '3', '70'))).toEqual({ score: '66.6%', verdict: FAIL });
  });
});

describe('T-S1.5 boundaries of the pass mark', () => {
  it('pass mark "0": 0 of 23 → "0.0%", Pass (0 ≥ 0)', () => {
    expect(isPass(0, 2300, 0)).toBe(true);
    expect(shown(vm('0', '23', '0'))).toEqual({ score: '0.0%', verdict: PASS });
  });

  it('pass mark "100": 23 of 23 → "100.0%", Pass (2,300,000 ≥ 2,300,000)', () => {
    expect(isPass(2300, 2300, 1000)).toBe(true);
    expect(scoreTenths(2300, 2300)).toBe(1000);
    expect(formatScore(1000)).toBe('100.0');
    expect(shown(vm('23', '23', '100'))).toEqual({ score: '100.0%', verdict: PASS });
  });
});

describe('T-S1.6 pass mark "100": 999999.99 of 1000000 → "99.9%", Fail', () => {
  it('99,999,999,000 < 100,000,000,000 and floors to 999 tenths', () => {
    expect(parseDecimal('999999.99', 2)).toEqual({ ok: true, value: 99_999_999 });
    expect(parseDecimal('1000000', 2)).toEqual({ ok: true, value: 100_000_000 });
    expect(isPass(99_999_999, 100_000_000, 1000)).toBe(false);
    expect(scoreTenths(99_999_999, 100_000_000)).toBe(999);
    expect(shown(vm('999999.99', '1000000', '100'))).toEqual({ score: '99.9%', verdict: FAIL });
  });

  it('the largest products stay exact safe integers', () => {
    expect(Number.isSafeInteger(100_000_000 * 1000)).toBe(true);
    expect(Number.isSafeInteger(1000 * 100_000_000)).toBe(true);
  });
});

describe('T-S1.7 0.01 of 1000000 at 70 → "0.0%", Fail', () => {
  it('1000 / 100,000,000 floors to 0 tenths; 1000 < 70,000,000,000', () => {
    expect(parseDecimal('0.01', 2)).toEqual({ ok: true, value: 1 });
    expect(scoreTenths(1, 100_000_000)).toBe(0);
    expect(formatScore(0)).toBe('0.0');
    expect(isPass(1, 100_000_000, 700)).toBe(false);
    expect(shown(vm('0.01', '1000000', '70'))).toEqual({ score: '0.0%', verdict: FAIL });
  });
});

describe('T-S1.8 carrying on after a result recalculates', () => {
  it('17.5 → 15.5 of 23 gives "67.3%" Fail; then pass mark 65 gives Pass with "67.3%"', () => {
    expect(shown(vm('17.5', '23', '70'))).toEqual({ score: '76.0%', verdict: PASS });
    expect(scoreTenths(1550, 2300)).toBe(673);
    expect(isPass(1550, 2300, 700)).toBe(false);
    expect(shown(vm('15.5', '23', '70'))).toEqual({ score: '67.3%', verdict: FAIL });
    expect(isPass(1550, 2300, 650)).toBe(true);
    expect(shown(vm('15.5', '23', '65'))).toEqual({ score: '67.3%', verdict: PASS });
  });
});

// Supporting tests for S-1 (not tied to one AC).

describe('S-1 supporting: score formatting (ADR-007)', () => {
  it.each([
    [760, '76.0'],
    [0, '0.0'],
    [1000, '100.0'],
    [999, '99.9'],
    [666, '66.6'],
    [5, '0.5'],
  ])('formatScore(%i) = "%s"', (tenths, text) => {
    expect(formatScore(tenths)).toBe(text);
  });

  it('floorDiv is exact at 10^11', () => {
    expect(floorDiv(100_000_000_000, 100_000_000)).toBe(1000);
    expect(floorDiv(99_999_999_999, 100_000_000)).toBe(999);
    expect(floorDiv(7, 7)).toBe(1);
    expect(floorDiv(6, 7)).toBe(0);
  });
});

describe('S-1 supporting: accepted number format (A-13, A-18)', () => {
  it.each([
    ['.5', 2, 50],
    ['5.', 2, 500],
    ['007', 2, 700],
    [' 017.5 ', 2, 1750],
    ['17.25', 2, 1725],
    ['0', 2, 0],
    ['69.9', 1, 699],
    ['100', 1, 1000],
  ])('parseDecimal(%j, %i) = %i', (raw, maxDp, value) => {
    expect(parseDecimal(raw, maxDp)).toEqual({ ok: true, value });
  });

  it.each(['', '   ', '.', ' . '])('%j is empty (value null)', (raw) => {
    expect(parseDecimal(raw, 2)).toEqual({ ok: true, value: null });
  });

  it.each(['abc', '17,5', '$17', '1.2.3', '1e400', '+5', '-1', '-', '17.555'])('%j is not accepted', (raw) => {
    expect(parseDecimal(raw, 2).ok).toBe(false);
  });
});

describe('S-1 supporting: states around the result', () => {
  it('earned or total empty → idle prompt M-1, no score', () => {
    for (const model of [vm('', '', '70'), vm('17.5', '', '70'), vm('', '23', '70'), vm('17.5', '   ', '70')]) {
      expect(model.state).toBe('idle');
      expect(model.state === 'idle' && model.message).toBe(MESSAGES['M-1']);
      expect(model.announcement).toBe('');
    }
  });

  it('pass mark empty → score still shown with M-2, no verdict', () => {
    const model = vm('17.5', '23', '');
    expect(model.state).toBe('pass-mark-empty');
    expect(model.state === 'pass-mark-empty' && model.score).toBe('76.0');
    expect(model.state === 'pass-mark-empty' && model.verdictMessage).toBe(MESSAGES['M-2']);
    expect(shown(model)).toBeNull();
  });

  // Until S-3 adds the error state and messages, invalid or impossible input simply shows no score.
  it.each([
    ['abc', '23', '70'],
    ['17.5', '0', '70'],
    ['23.5', '23', '70'],
    ['10', '1000000.01', '70'],
    ['17.5', '23', '100.1'],
    ['17.5', '23', 'seventy'],
    ['1'.repeat(400), '23', '70'],
    ['17.5', '9'.repeat(400), '70'],
  ])('%j of %j at %j shows no score or verdict', (earned, total, pass) => {
    const model = vm(earned, total, pass);
    expect(shown(model)).toBeNull();
    expect(model.state).not.toBe('pass-mark-empty');
  });

  it('total "1000000" is accepted (maximum allowed)', () => {
    expect(shown(vm('10', '1000000', '70'))?.score).toBe('0.0%');
  });

  it('no view-model text is ever NaN, Infinity, undefined or blank for valid input', () => {
    const cases: Array<[string, string, string]> = [
      ['17.5', '23', '70'], ['0', '0.01', '0'], ['1000000', '1000000', '100'], ['0.01', '1000000', '0'],
    ];
    for (const [earned, total, pass] of cases) {
      const model = vm(earned, total, pass);
      const text = JSON.stringify(model);
      for (const bad of ['NaN', 'Infinity', 'undefined']) expect(text).not.toContain(bad);
      expect(shown(model)?.score.length ?? 0).toBeGreaterThan(1);
    }
  });
});
import type { Locator, Page } from '@playwright/test';
import { test, expect } from './fixtures';
import { MESSAGES } from '../../src/messages';

// S-1 Score and pass/fail verdict (test-plan.md E-S1.1..E-S1.8).
// Numbers are quoted exactly from the ACs; words come from messages.ts (M-4 "Pass", M-5 "Fail").

const PASS = MESSAGES['M-4'];
const FAIL = MESSAGES['M-5'];

interface Card {
  earned: Locator;
  total: Locator;
  pass: Locator;
  result: Locator;
  score: Locator;
  verdict: Locator;
  status: Locator;
}

function card(page: Page): Card {
  const result = page.getByRole('region', { name: MESSAGES['M-39'] });
  return {
    earned: page.getByLabel(MESSAGES['M-34'], { exact: true }),
    total: page.getByLabel(MESSAGES['M-35'], { exact: true }),
    pass: page.getByLabel(MESSAGES['M-36'] + MESSAGES['M-37'], { exact: true }),
    result,
    score: result.locator('.score'),
    verdict: result.locator('.verdict'),
    status: page.getByRole('status'),
  };
}

/** Score and verdict as the user sees them; the verdict also carries its icon and colour class. */
async function expectOutcome(c: Card, score: string, verdict: string): Promise<void> {
  await expect(c.score).toHaveText(score);
  await expect(c.verdict).toHaveText(verdict);
  await expect(c.verdict).toHaveClass(new RegExp(`verdict--${verdict === PASS ? 'pass' : 'fail'}`));
  await expect(c.verdict.locator('svg')).toHaveAttribute('aria-hidden', 'true');
  await expect(c.result).not.toContainText(MESSAGES['M-1']);
}

async function enter(c: Card, earned: string, total: string, pass?: string): Promise<void> {
  if (pass !== undefined) await c.pass.fill(pass);
  await c.total.fill(total);
  await c.earned.fill(earned);
}

test.beforeEach(async ({ page }) => {
  await page.goto('./');
});

test('E-S1.1 typing "17.5" of "23" with the pre-filled "70" shows "76.0%" and "Pass" with no button or key', async ({ page }) => {
  const c = card(page);
  await expect(c.pass).toHaveValue('70');
  await expect(c.score).toHaveCount(0);

  await c.earned.pressSequentially('17.5');
  await expect(c.result).toContainText(MESSAGES['M-1']);
  await c.total.pressSequentially('23');

  await expectOutcome(c, '76.0%', PASS);
  // The "%" is the half-size unit of the score.
  await expect(c.score.locator('.score-unit')).toHaveText('%');
  // Screen readers get the same outcome after the debounce.
  await expect(c.status).toContainText(`76.0%, ${PASS}`);
});

test('E-S1.2 "17.5" of "25" (exactly 70%) shows "70.0%" and "Pass"', async ({ page }) => {
  const c = card(page);
  await enter(c, '17.5', '25');
  await expectOutcome(c, '70.0%', PASS);
});

test('E-S1.3 "17.49" of "25" (69.96%) shows "69.9%" and "Fail", never "70.0%"', async ({ page }) => {
  const c = card(page);
  await c.total.fill('25');
  await c.earned.focus();
  const afterEachKey: Array<[string, string]> = [
    ['1', '4.0%'],
    ['7', '68.0%'],
    ['.', '68.0%'],
    ['4', '69.6%'],
    ['9', '69.9%'],
  ];
  for (const [key, score] of afterEachKey) {
    await page.keyboard.type(key);
    await expect(c.score).toHaveText(score);
    await expect(c.result).not.toContainText('70.0%');
  }
  await expect(c.earned).toHaveValue('17.49');
  await expectOutcome(c, '69.9%', FAIL);
});

test('E-S1.4 "2" of "3" shows "66.6%" (rounded down, not "66.7%") and "Fail"', async ({ page }) => {
  const c = card(page);
  await enter(c, '2', '3');
  await expectOutcome(c, '66.6%', FAIL);
  await expect(c.result).not.toContainText('66.7%');
});

test('E-S1.5 pass mark "0": "0" of "23" → "0.0%" Pass; pass mark "100": "23" of "23" → "100.0%" Pass', async ({ page }) => {
  const c = card(page);
  await enter(c, '0', '23', '0');
  await expectOutcome(c, '0.0%', PASS);

  await enter(c, '23', '23', '100');
  await expectOutcome(c, '100.0%', PASS);
});

test('E-S1.6 pass mark "100": "999999.99" of "1000000" shows "99.9%" and "Fail"', async ({ page }) => {
  const c = card(page);
  await enter(c, '999999.99', '1000000', '100');
  await expectOutcome(c, '99.9%', FAIL);
});

test('E-S1.7 "0.01" of "1000000" with pass mark "70" shows "0.0%" and "Fail"', async ({ page }) => {
  const c = card(page);
  await enter(c, '0.01', '1000000', '70');
  await expectOutcome(c, '0.0%', FAIL);
});

test('E-S1.8 after "76.0%" Pass, earned "15.5" → "67.3%" Fail; then pass mark "65" → Pass, score stays "67.3%"', async ({ page }) => {
  const c = card(page);
  await enter(c, '17.5', '23');
  await expectOutcome(c, '76.0%', PASS);

  await c.earned.fill('15.5');
  await expectOutcome(c, '67.3%', FAIL);

  await c.pass.fill('65');
  await expectOutcome(c, '67.3%', PASS);
  await expect(c.earned).toHaveValue('15.5');
  await expect(c.total).toHaveValue('23');
});
import { test as base, expect } from '@playwright/test';

// DoD: any console error, console warning or uncaught page error fails the test.
export const test = base.extend<{ consoleGuard: void }>({
  consoleGuard: [
    async ({ page }, use) => {
      const problems: string[] = [];
      page.on('console', (msg) => {
        if (msg.type() === 'error' || msg.type() === 'warning') {
          problems.push(`console.${msg.type()}: ${msg.text()}`);
        }
      });
      page.on('pageerror', (err) => problems.push(`pageerror: ${err.message}`));
      await use();
      expect(problems, 'console errors, warnings or page errors').toEqual([]);
    },
    { auto: true },
  ],
});

export { expect };

import { renderResult, renderShell, type ShellElements } from './render';
import { toViewModel, type RawInputs } from './view-model';

/** Screen-reader status text is set this long after the last input, so "17.5" is read once (ui-design.md). */
const ANNOUNCE_DELAY_MS = 500;

function readInputs(shell: ShellElements): RawInputs {
  return { earned: shell.inputs.earned.value, total: shell.inputs.total.value, pass: shell.inputs.pass.value };
}

/** Debounced writer for the role="status" node; it writes only text that differs from the last one. */
function createAnnouncer(status: HTMLElement): (text: string) => void {
  let timer: number | undefined;
  let lastText = '';
  return (text) => {
    window.clearTimeout(timer);
    timer = window.setTimeout(() => {
      if (text === lastText) return;
      status.textContent = text;
      lastText = text;
    }, ANNOUNCE_DELAY_MS);
  };
}

/** Mounts the app into `root` and recalculates on every input event (A-7: no Calculate button). */
export function mountApp(root: HTMLElement | null): ShellElements | null {
  if (root === null) return null;
  const shell = renderShell(root);
  const announce = createAnnouncer(shell.status);

  const update = (): void => {
    const vm = toViewModel(readInputs(shell));
    renderResult(shell.resultBody, vm); // visual update is immediate
    announce(vm.announcement);
  };

  for (const input of Object.values(shell.inputs)) input.addEventListener('input', update);
  update();
  return shell;
}
import { ESC_KEY_LABEL, MESSAGES, SCORE_UNIT } from '../messages';
import { el, svgEl } from './dom';
import type { Verdict, ViewModel } from './view-model';

export type FieldName = 'earned' | 'total' | 'pass';

export interface ShellElements {
  readonly inputs: Readonly<Record<FieldName, HTMLInputElement>>;
  readonly errors: Readonly<Record<FieldName, HTMLParagraphElement>>;
  readonly resultBody: HTMLDivElement;
  readonly status: HTMLDivElement;
  readonly nextLearner: HTMLButtonElement;
}

/** Initial values on load and after reload (technical-design.md §State model). */
export const INITIAL_VALUES: Readonly<Record<FieldName, string>> = { earned: '', total: '', pass: '70' };

const FIELD_IDS: Readonly<Record<FieldName, string>> = { earned: 'earned', total: 'total', pass: 'pass-mark' };

function createInput(field: FieldName): HTMLInputElement {
  const input = el('input', {
    class: 'input',
    id: FIELD_IDS[field],
    name: field,
    type: 'text',
    inputmode: 'decimal',
    autocomplete: 'off',
    spellcheck: 'false',
    'aria-describedby': `${FIELD_IDS[field]}-error`,
  });
  input.value = INITIAL_VALUES[field];
  return input;
}

function createErrorSlot(field: FieldName): HTMLParagraphElement {
  return el('p', { class: 'field-error', id: `${FIELD_IDS[field]}-error` });
}

function createField(
  field: FieldName,
  labelChildren: ReadonlyArray<Node | string>,
  input: HTMLInputElement,
  error: HTMLParagraphElement,
): HTMLDivElement {
  const control =
    field === 'pass'
      ? el('div', { class: 'input-wrap' }, [input, el('span', { class: 'suffix', 'aria-hidden': 'true' }, [MESSAGES['M-38']])])
      : input;
  return el('div', { class: `field field--${field}` }, [
    el('label', { class: 'label', for: FIELD_IDS[field] }, labelChildren),
    control,
    error,
  ]);
}

/** A muted message in the result body, e.g. the idle prompt M-1; no score. */
function resultMessage(text: string): HTMLParagraphElement {
  return el('p', { class: 'result-msg' }, [text]);
}

/** Tick (Pass) and cross (Fail) glyphs from the mockup, drawn on a 24 × 24 grid. */
const VERDICT_GLYPHS: Readonly<Record<Verdict, string>> = {
  pass: 'M6.5 12.5l3.8 3.8 7.4-8.3',
  fail: 'M8 8l8 8M16 8l-8 8',
};

/** Score "76.0" with the half-size muted "%" unit. */
function scoreNode(score: string): HTMLParagraphElement {
  return el('p', { class: 'score' }, [score, el('span', { class: 'score-unit' }, [SCORE_UNIT])]);
}

/** Verdict block: decorative tick/cross disc + the word, so the verdict never relies on colour alone. */
function verdictNode(verdict: Verdict, text: string): HTMLParagraphElement {
  const glyph = svgEl('svg', { viewBox: '0 0 24 24', 'aria-hidden': 'true', focusable: 'false' }, [
    svgEl('path', { class: 'i-stroke', d: VERDICT_GLYPHS[verdict] }),
  ]);
  return el('p', { class: `verdict verdict--${verdict}` }, [
    el('span', { class: 'verdict-disc' }, [glyph]),
    el('span', {}, [text]),
  ]);
}

/** Renders the result body for a view model. Displays only; never calculates. */
export function renderResult(resultBody: HTMLElement, vm: ViewModel): void {
  switch (vm.state) {
    case 'idle':
      resultBody.replaceChildren(resultMessage(vm.message));
      return;
    case 'pass-mark-empty':
      resultBody.replaceChildren(
        el('div', { class: 'outcome' }, [scoreNode(vm.score), el('p', { class: 'verdict-msg' }, [vm.verdictMessage])]),
      );
      return;
    case 'result':
      resultBody.replaceChildren(
        el('div', { class: 'outcome' }, [scoreNode(vm.score), verdictNode(vm.verdict, vm.verdictText)]),
      );
      return;
  }
}

/** Builds the static card once from messages.ts and mounts it into `root`. Never calculates. */
export function renderShell(root: HTMLElement): ShellElements {
  const inputs = { earned: createInput('earned'), total: createInput('total'), pass: createInput('pass') };
  const errors = { earned: createErrorSlot('earned'), total: createErrorSlot('total'), pass: createErrorSlot('pass') };

  const resultBody = el('div', { class: 'result-body' }, [resultMessage(MESSAGES['M-1'])]);
  const status = el('div', { class: 'sr-only', role: 'status', 'aria-live': 'polite', 'aria-atomic': 'true' });
  const nextLearner = el('button', { class: 'btn', type: 'button', 'aria-keyshortcuts': 'Escape' }, [MESSAGES['M-25']]);

  const hintLead = MESSAGES['M-40'].slice(0, -ESC_KEY_LABEL.length);

  const card = el('article', { class: 'card', 'aria-labelledby': 'card-title' }, [
    el('header', { class: 'card-head' }, [
      el('p', { class: 'eyebrow' }, [MESSAGES['M-31']]),
      el('h1', { class: 'title', id: 'card-title' }, [MESSAGES['M-32']]),
      el('p', { class: 'sub' }, [MESSAGES['M-33']]),
    ]),
    el('div', { class: 'fields' }, [
