const browser = await chromium.launch();

async function newPage(opts = {}) {
  const ctx = await browser.newContext(opts);
  const page = await ctx.newPage();
  const tag = JSON.stringify(opts);
  page.on('console', (m) => out.console.push(`${tag} console.${m.type()}: ${m.text()}`));
  page.on('pageerror', (e) => out.console.push(`${tag} pageerror: ${e.message}`));
  page.on('requestfailed', (r) => out.console.push(`${tag} requestfailed: ${r.url()}`));
  await page.goto(URL);
  await page.getByLabel('Marks earned', { exact: true }).waitFor();
  return page;
}

const F = (page) => ({
  earned: page.getByLabel('Marks earned', { exact: true }),
  total: page.getByLabel('Total marks possible', { exact: true }),
  pass: page.getByLabel('Pass mark (percent)', { exact: true }),
});

async function state(page) {
  return page.evaluate(() => {
    const r = document.querySelector('.result-body');
    const s = document.querySelector('.score');
    const v = document.querySelector('.verdict');
    return {
      earned: document.querySelector('#earned').value,
      total: document.querySelector('#total').value,
      pass: document.querySelector('#pass-mark').value,
      score: s ? s.textContent : null,
      verdict: v ? v.textContent : null,
      verdictClass: v ? v.className : null,
      result: r ? r.textContent : null,
      status: document.querySelector('[role="status"]').textContent,
      url: location.href,
    };
  });
}

// Type like a user: focus the field, select all, type new text key by key (empty text = Backspace).
async function typeInto(page, loc, text) {
  await loc.click();
  await page.keyboard.press('ControlOrMeta+a');
  if (text === '') await page.keyboard.press('Backspace');
  else await page.keyboard.type(text, { delay: 20 });
}

async function settle(page) {
  await page.waitForTimeout(700); // > 500 ms status debounce
}

async function runAc(id, steps, method) {
  const page = await newPage();
  const f = F(page);
  const observed = [];
  for (const [earned, total, pass] of steps) {
    if (method === 'type') {
      if (pass !== undefined) await typeInto(page, f.pass, pass);
      if (total !== undefined) await typeInto(page, f.total, total);
      if (earned !== undefined) await typeInto(page, f.earned, earned);
    } else {
      if (pass !== undefined) await f.pass.fill(pass);
      if (total !== undefined) await f.total.fill(total);
      if (earned !== undefined) await f.earned.fill(earned);
    }
    await settle(page);
    observed.push(await state(page));
  }
  out.acs.push({ id, method, observed });
  await page.context().close();
}

